/* LD_PRELOAD probe: emit a line on every X509_STORE_lock() call so we can
 * attribute store locking to ssl.SSLContext.cert_store_stats()/get_ca_certs().
 * Local test fixture only. */
#define _GNU_SOURCE
#include <dlfcn.h>
#include <unistd.h>

static int (*real_lock)(void *);
static const char msg[] = "SSLSTORE_LOCK\n";

int X509_STORE_lock(void *ctx)
{
    if (!real_lock) {
        real_lock = (int (*)(void *))dlsym(RTLD_NEXT, "X509_STORE_lock");
    }
    write(2, msg, sizeof(msg) - 1);
    return real_lock(ctx);
}

/* LD_PRELOAD probe: emit a line on every X509_STORE_lock() call so we can
 * attribute store locking to ssl.SSLContext.cert_store_stats()/get_ca_certs().
 * Local test fixture only. */
#define _GNU_SOURCE
#include <dlfcn.h>
#include <unistd.h>

static int (*real_lock)(void *);
static void *crypto;

static void *resolve_crypto(void)
{
    void *h = dlopen("libcrypto.so.3", RTLD_NOW | RTLD_NOLOAD);
    if (h == NULL) {
        h = dlopen("libcrypto.so.3", RTLD_NOW);
    }
    return h;
}

int X509_STORE_lock(void *ctx)
{
    const char msg[] = "SSLSTORE_LOCK\n";
    write(2, msg, sizeof(msg) - 1);
    if (real_lock == NULL) {
        crypto = resolve_crypto();
        real_lock = (int (*)(void *))dlsym(crypto, "X509_STORE_lock");
    }
    if (real_lock == NULL) {
        const char fail[] = "SSLSTORE_LOCK_UNRESOLVED\n";
        write(2, fail, sizeof(fail) - 1);
        return 0;
    }
    return real_lock(ctx);
}

